import React,{useEffect,useRef,useState} from 'react';
import CatalogModal from './CatalogModal';
import {useI18n} from '../i18n';
import {publicDataBase,publicDataUrl,readPublicData} from '../publicDataApi';
import './ApiService.css';

export default function PublicDataExplorer({onClose,onPublish}){
  const {t}=useI18n();const [sources,setSources]=useState([]),[sourceId,setSourceId]=useState(''),[query,setQuery]=useState({from:'',to:'',timeField:'',recordsPath:'',fields:'',limit:'100'}),[latest,setLatest]=useState(false),[result,setResult]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(true),[lastQuery,setLastQuery]=useState(null),[partial,setPartial]=useState(false);const active=useRef(null);
  const source=sources.find(s=>s.id===sourceId);
  useEffect(()=>{const c=new AbortController();active.current=c;readPublicData(publicDataUrl('/datasets'),{signal:c.signal}).then(d=>{setSources(d.datasets);setPartial(Boolean(d.partial));setSourceId(d.datasets[0]?.id||'');}).catch(e=>{if(!c.signal.aborted)setError(e.message);}).finally(()=>{if(!c.signal.aborted)setBusy(false);});return()=>active.current?.abort();},[]);
  const run=async(offset=0)=>{active.current?.abort();const c=new AbortController();active.current=c;setBusy(true);setError('');const params=offset?{...lastQuery.params,offset,revision:result.revision}:{...query};const path=offset?lastQuery.path:`/datasets/${sourceId}/${latest?'latest':'data'}`;try{const data=await readPublicData(publicDataUrl(path,params),{signal:c.signal});setResult(data);setLastQuery({path,params});}catch(e){if(!c.signal.aborted){setError(e.message);setResult(null);}}finally{if(!c.signal.aborted)setBusy(false);}};
  const update=(key,value)=>{setQuery(q=>({...q,[key]:value}));setResult(null);};
  return <CatalogModal label={t('Query public data')} onClose={onClose} className="api-service-dialog"><div className="api-service-form" translate="no">
    <div className="api-service-heading"><h2>{t('Query public data')}</h2><button className="catalog-icon-button" aria-label={t('Close')} onClick={onClose}>×</button></div><p>{t('Query existing public Pod files. Original records and histories remain unchanged.')}</p>
    <label>{t('Dataset')}<select value={sourceId} disabled={busy} onChange={e=>{setSourceId(e.target.value);setQuery({from:'',to:'',timeField:'',recordsPath:'',fields:'',limit:'100'});setResult(null);}}><option value="">{t('Select dataset')}</option>{sources.map(s=><option key={s.id} value={s.id}>{s.title} / {s.podName}</option>)}</select></label>
    {partial&&<p className="api-service-note">{t('Some catalog records are currently unavailable. Only discovered public sources are listed.')}</p>}
    <div className="api-service-grid">{[['from','From (inclusive, ISO timestamp)'],['to','To (exclusive, ISO timestamp)']].map(([key,label])=><label key={key}>{t(label)}<input disabled={busy} value={query[key]} placeholder="2026-10-22T00:00:00Z" onChange={e=>update(key,e.target.value)}/></label>)}<label>{t('Records per page')}<input disabled={busy} type="number" min="1" max="1000" value={query.limit} onChange={e=>update('limit',e.target.value)}/></label></div>
    <details><summary>{t('Field selection (optional)')}</summary><div className="api-service-grid">{[['timeField','Time field or JSON Pointer'],['recordsPath','Record array JSON Pointer'],['fields','Output fields (comma-separated)']].map(([key,label])=><label key={key}>{t(label)}<input disabled={busy} value={query[key]} onChange={e=>update(key,e.target.value)}/></label>)}</div><p>{t('Time fields are detected only when every record has a valid timestamp. You can specify the field explicitly.')}</p></details>
    <label className="api-service-check"><input disabled={busy} type="checkbox" checked={latest} onChange={e=>{setLatest(e.target.checked);setResult(null);}}/>{t('Latest timestamp only')}</label>
    {error&&<p role="alert" className="api-service-error">{t(error)}</p>}
    <div className="api-service-actions"><button className="catalog-button catalog-button--primary" disabled={busy||!source} onClick={()=>run()}>{t(busy?'Loading...':'Run query')}</button><a className="catalog-button" href={publicDataBase()+'/openapi.json'} target="_blank" rel="noopener noreferrer">{t('API documentation')}</a>{source&&onPublish&&<button className="catalog-button" disabled={busy} onClick={()=>onPublish({title:source.title+' API',description:source.description||t('Read-only API for public Pod data.'),publisher:source.podName,endpointURL:publicDataUrl(`/datasets/${source.id}/data`),endpointDescription:new URL(publicDataBase()+'/openapi.json',window.location.origin).href,authentication:'public',servesDataset:[source.datasetUrl]})}>{t('Add this API to catalog')}</button>}</div>
    {result&&<section aria-live="polite"><h3>{t('Query result')}</h3><p>{result.count} / {result.total} {t('records')}</p><p>{t('Source')}: <code>{result.sourceUrl}</code></p><pre tabIndex="0">{JSON.stringify(result.records,null,2).slice(0,50000)}{JSON.stringify(result.records).length>50000?'\n'+t('Preview shortened. Use the API for the full page.'):''}</pre><div className="api-service-actions">{['json','csv','ndjson'].map(format=><a className="catalog-button" key={format} href={publicDataUrl(lastQuery.path,{...lastQuery.params,revision:result.revision,format})} target="_blank" rel="noopener noreferrer">{format.toUpperCase()}</a>)}{result.nextOffset!==null&&<button className="catalog-button" disabled={busy} onClick={()=>run(result.nextOffset)}>{t('Next page')}</button>}</div></section>}
  </div></CatalogModal>;
}
